"use client"

import * as React from "react"
import { Slot } from "radix-ui"

import { MARK_WIPE, useMarkInk } from "@/hooks/use-mark-ink"
import { useMergedRef } from "@/lib/ink/react"
import { highlightRecipe } from "@/lib/ink/recipes/highlight-ink"
import type { HighlightTone } from "@/lib/ink/recipes/text-marks-ink"
import { cn } from "@/lib/utils"

const FAT = { light: 0.82, regular: 1, heavy: 1.22 } as const

function Highlight({
  tone = "yellow",
  weight = "regular",
  cover = "full",
  animate = false,
  show = true,
  delay,
  seed,
  asChild = false,
  className,
  children,
  ref,
  ...props
}: React.ComponentProps<"mark"> & {
  tone?: HighlightTone
  weight?: keyof typeof FAT
  cover?: "full" | "under"
  animate?: boolean
  show?: boolean
  delay?: number
  seed?: string | number
  asChild?: boolean
}) {
  const { hostRef, hostProps, nodes } = useMarkInk({
    recipe: highlightRecipe,
    params: { tone, fat: FAT[weight], cover },
    kind: "highlight",
    seed,
    animate,
    show,
    delay,
  })
  const Comp = asChild ? Slot.Root : "mark"
  return (
    <Comp
      data-slot="highlight"
      data-tone={tone}
      data-cover={cover}
      ref={useMergedRef<HTMLElement>(hostRef, ref as React.Ref<HTMLElement> | undefined)}
      {...hostProps}
      className={cn(
        "relative isolate text-inherit data-[ink-ready]:bg-transparent data-[mark=off]:bg-transparent not-focus-visible:outline-none forced-colors:not-focus-visible:outline-none!",
        animate && "bg-transparent noscript:bg-hi-select",
        animate && MARK_WIPE,
        className,
      )}
      {...props}
    >
      <Slot.Slottable>{children}</Slot.Slottable>
      {nodes}
    </Comp>
  )
}

export { Highlight }

import { highlight } from '@/lib/ink/fills'
import { defineRecipe } from '@/lib/ink/recipes'
import { highlighterPen, overshoot, type HighlightTone, type LineParams } from '@/lib/ink/recipes/text-marks-ink'

export interface HighlightParams extends LineParams {
  tone: HighlightTone
  fat?: number
  cover?: 'full' | 'under'
}

export const highlightRecipe = defineRecipe<HighlightParams>({
  id: 'highlight',
  kind: 'highlight',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }, p, ctx) {
    const { pen, opts } = highlighterPen(p.tone)
    const o = overshoot(p.fs)
    const under = p.cover === 'under'
    const top = under ? p.base - p.xh * 0.42 : p.base - p.cap - p.fs * 0.14
    const bot = p.base + p.desc * (under ? 0.95 : 0.85) + p.fs * 0.06
    const band = Math.min(h, (bot - top) * (p.fat ?? 1))
    const y = Math.max(0, top + ((bot - top) - band) / 2)
    const x0 = p.first ? -o * 0.6 : -1
    const x1 = p.last ? w + o * 0.6 : w + 1
    ink.layer('rest', () => {
      highlight(ink, x0, y, x1 - x0, band, { pen, opts })
      if (!ctx.calm && x1 - x0 > 4.5 * p.fs) {
        const r = ink.next('again')
        highlight(ink, x0 + r.range(0.1, 0.25) * (x1 - x0), y + r.range(-1.2, 1.2), (x1 - x0) * r.range(0.4, 0.62), band * 0.8, { pen, opts: { ...opts, alpha: (opts.alpha ?? 1) * 0.5 } })
      }
    })
  },
})

